(function(){
'use strict';
const C=TrainingCore,D=TRAINING_DICTIONARY,store=new TrainingStore();
let github=null,githubReceipt=null,githubNotice=false,quickRunning=false,quickClock=new TrainingQuickClock(),quickSubmitting=false,quickFeedback=null;
let data=C.initial(),route='quiz',direction='enRu',quizID=null,showResults=false,selectedWord=null,selectedHistory=null,selection=null,search='',filter='all',ascending=true,busy=false,storageReady=false,error=null,errorID=null,editing=null,originalEditor='',editorError=null,editorDuplicate=null,importer=null,toastTimer;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=d=>d==='enRu'?'English → Russian':'Russian → English';
const date=t=>t===null?'Not practiced':new Date(t).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const dateOnly=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const active=()=>data.sessions.find(s=>s.status==='in_progress');
function appearance(){return ['light','dark','system'].includes(data.settings.appearance)?data.settings.appearance:'dark';}
function applyAppearance(){
 const mode=appearance();document.documentElement.dataset.theme=mode;
 const isDark=mode==='dark'||(mode==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches);
 const toggle=$('#theme-toggle');if(toggle){toggle.textContent=isDark?'☀ Switch to Light':'☾ Switch to Dark';toggle.setAttribute('aria-label',isDark?'Switch to light mode':'Switch to dark mode');toggle.disabled=!storageReady||busy;}
}
async function setAppearance(mode){
 if(!['light','dark','system'].includes(mode))return;
 await mutation(state=>{state.settings.appearance=mode;});render();
}
const words=()=>data.words.filter(w=>w.deletedAt===null);
const wordTitle=w=>w.content.english_term||'Untitled draft';
const badge=(s,color='')=>`<span class="badge ${color}">${esc(s)}</span>`;
const icon=name=>{const paths={quiz:'<rect x="4" y="5" width="16" height="14" rx="3"/><path d="M8 2h8M8 22h8M9 10l6 2-6 3z"/>',vocabulary:'<path d="M4 4h6a3 3 0 013 3v14a3 3 0 00-3-3H4zm16 0h-4a3 3 0 00-3 3v14a3 3 0 013-3h4z"/>',history:'<path d="M3 12a9 9 0 119 9M3 4v8h7M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16M9 4v6M15 14v6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||''}</svg>`;};
const heading=(name,sub,action='')=>`<div class="heading"><div><div class="eyebrow">ENGLISH TRAINING</div><h1>${esc(name)}</h1><p class="sub">${esc(sub)}</p></div>${action}</div>`;
const button=(label,action,classes='',extra='')=>`<button type="button" class="${classes}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(glyph,name,text,action='')=>`<div class="empty"><div class="glyph" aria-hidden="true">${glyph}</div><h2>${esc(name)}</h2><p>${esc(text)}</p>${action}</div>`;
function notify(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),5000);}
function friendly(e){if(e?.name==='QuotaExceededError')return 'Browser storage is full. No changes were saved. Free device space and retry.';return e?.message||'The action could not be completed.';}
function fail(e){error=friendly(e);errorID=e?.existingID||null;renderAlert();}
function renderAlert(){const el=$('#alert-region');el.innerHTML=error?`<div class="notice error" role="alert">${esc(error)}<div class="error-actions">${errorID?button('Open Existing Entry','open-duplicate','small'):''}${button('Dismiss','dismiss-error','small')}</div></div>`:'';}
async function mutation(fn){if(busy)return null;busy=true;syncBusy();try{const result=await store.transact(fn);data=result.state;return result.result;}catch(e){fail(e);return null;}finally{busy=false;syncBusy();}}
function syncBusy(){applyAppearance();document.querySelectorAll('[data-save-action]').forEach(b=>{const action=b.dataset.action;b.disabled=busy||!storageReady||(action==='apply'&&selection===null)||(action==='start'&&!words().some(w=>w.status==='ready'));});}
function render(){
 applyAppearance();
 const focused=document.activeElement,focusID=focused?.id,position=focused?.selectionStart,meaningsOpen=!!$('#supported-meanings')?.open;
 document.querySelectorAll('.nav button').forEach(b=>{const on=b.dataset.route===route;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 $('#resume-side').classList.toggle('hidden',!active());$('#storage-label').textContent=storageReady?'Saved in this browser':'Checking browser storage…';
 if(!storageReady){$('#page').innerHTML=empty('↻','Opening your learning space','Checking whether this browser can save your vocabulary and quizzes.');renderAlert();return;}
 $('#page').innerHTML=route==='quiz'?quizPage():route==='vocabulary'?vocabularyPage():route==='history'?historyPage():settingsPage();renderAlert();syncBusy();refreshGitHubStatus();refreshQuickClock();
 if(meaningsOpen&&$('#supported-meanings'))$('#supported-meanings').open=true;
 if(focusID&&document.getElementById(focusID)){const field=document.getElementById(focusID);field.focus();if(typeof field.setSelectionRange==='function'&&position!==null)try{field.setSelectionRange(position,position);}catch{}}
}
function quizPage(){
 const session=data.sessions.find(s=>s.id===quizID);
 if(session?.kind==='quick_match')return quickPage(session);
 if(session)return showResults?`<div class="stack">${review(session)}<div>${button('Back to Quiz Setup','quiz-setup','primary')}</div></div>`:activeQuiz(session);
 const ready=words().filter(w=>w.status==='ready'),completed=data.sessions.filter(s=>s.status==='completed'),current=data.sessions.find(s=>s.status==='in_progress'&&s.kind!=='quick_match');
 const due=ready.filter(w=>{const l=data.learning[`${w.id}:${direction}`];return l?.nextReview!==null&&l?.nextReview<=Date.now();}).length;
 return `${heading('Make every word count.','Your daily space to practice, remember, and grow.')}
 <div class="stack"><section class="card quick-intro"><div class="eyebrow">QUICK MATCH · ENGLISH → RUSSIAN</div><h2>Know it in four seconds.</h2><p class="sub">30 words. Two Russian meanings, or “I don’t know”. Pick an answer to move on immediately. Timeouts count as not correct. Your answers update the same word ratings and review schedule.</p><div class="row wrap block"><span class="badge">30 questions</span><span class="badge">4 seconds each</span></div>${button(data.sessions.some(s=>s.kind==='quick_match'&&s.status==='in_progress')?'Resume timed game':'Start timed game','quick-start','primary block','data-save-action')}</section><div class="hero"><div class="hero-art" aria-hidden="true"><span class="letter-tile first">A</span><span class="letter-tile second">я</span><span class="studio-spark">✳</span></div><span class="hero-stamp" aria-hidden="true">SMALL STEPS. BIG ENERGY.</span><div class="hero-text"><div class="eyebrow">A LITTLE, EVERY DAY</div><h2 style="font-size:26px;line-height:1.4">Small practice.<br><em>Lasting confidence.</em></h2><p class="sub">Five questions. Real-world context. A little more confidence with every session.</p></div></div>
 <div class="stats"><div class="card stat"><div class="caption">Ready vocabulary</div><div class="value">${ready.length}</div></div><div class="card stat"><div class="caption">Due in this direction</div><div class="value">${due}</div></div><div class="card stat"><div class="caption">Completed quizzes</div><div class="value">${completed.length}</div></div></div>
 ${current?`<div class="card row between wrap-mobile"><div>${badge('IN PROGRESS','orange')}<h2 style="margin-top:12px">Your next question is waiting.</h2><p class="sub">${title(current.direction)} · ${current.answers.length} of 5 answers saved</p></div>${button('Resume Quiz →','resume','primary')}</div>`:''}
 <section class="card"><h2>Choose your direction</h2><p class="caption" style="margin-top:7px">Each direction has its own review schedule.</p><div class="directions">${['enRu','ruEn'].map(d=>`<button type="button" class="direction ${direction===d?'selected':''}" data-action="direction" data-id="${d}" aria-pressed="${direction===d}"><span class="glyph" aria-hidden="true">${d==='enRu'?'A → я':'я → A'}</span><strong>${title(d)}</strong><span class="caption">${d==='enRu'?'Read English in context. Recognize its Russian meaning.':'Read Russian in context. Find the English expression.'}</span></button>`).join('')}</div><div class="row between wrap-mobile"><span class="caption">5 questions · 5 choices · your pace</span>${button(current?'Resume Quiz →':'Start Quiz →',current?'resume':'start','primary',`data-save-action ${!ready.length&&!current?'disabled':''}`)}</div></section>
 ${!ready.length?`<div class="card">${empty('+','Start with your first word','Add a meaning, translations, and examples. Save unfinished work as a draft.',button('Add Word','add-word','primary'))}</div>`:''}<p class="footer-note">New words come first, then due reviews. Fewer than five ready words? We’ll safely reuse them. Unverified meanings are rejected rather than guessed.</p></div>`;
}

function quickReady(session){return heading('Quick Match','30 questions · 4 seconds each')+'<section class="card quick-intro"><h2>Ready when you are.</h2><p class="sub">Choose the correct Russian meaning. “I don’t know” and timeouts earn no point. The game runs only after you press Start or Resume.</p><p class="caption block">'+session.answers.length+' of 30 answers already saved. If the last question’s deadline passed, it will count as a timeout when you resume.</p>'+button('Resume game','quick-start','primary block','data-save-action data-id="'+esc(session.id)+'"')+'</section>'}

function quickChoiceButtons(q,answer=null){return '<div class="choices quick-choices" role="group" aria-label="Russian translations">'+[...q.choices,{id:'unknown',label:'I don’t know'}].map((c,i)=>{const correct=!!answer&&c.id===q.correctID,wrong=!!answer&&c.id===answer.selectedID&&answer.outcome==='incorrect';return button('<span class="num">'+(i<2?i+1:'?')+'</span><span class="quick-choice-label">'+esc(c.label)+'</span>'+(correct?'<span class="quick-choice-mark" aria-label="Correct translation">✓</span>':wrong?'<span class="quick-choice-mark" aria-label="Incorrect choice">×</span>':''),'quick-answer','choice'+(i===2?' quick-unknown':'')+(correct?' correct':'')+(wrong?' wrong':''),'data-id="'+esc(c.id)+'" data-question="'+esc(q.id)+'" '+(answer?'disabled':'data-save-action'))}).join('')+'</div>'}
function quickFeedbackPage(session){
 const {question:q,answer:a}=quickFeedback,correct=q.choices.find(c=>c.id===q.correctID),positive=a.outcome==='correct',label=positive?'Correct!':a.reason==='timeout'?'Time’s up':a.reason==='unknown'?'I don’t know':'Incorrect';
 return heading('Quick Match','Your answer is saved.',button('Leave game','quick-leave'))+'<section class="card question quick-question"><div class="eyebrow">ENGLISH WORD</div><h2 class="prompt">'+esc(q.prompt)+'</h2></section>'+quickChoiceButtons(q,a)+'<div class="quick-instant-feedback '+(positive?'is-correct':'is-incorrect')+'" role="status" aria-live="assertive"><strong>'+(positive?'✓ ':'✕ ')+label+'</strong><p>Correct translation: '+esc(correct.label)+'</p></div><p class="caption block">Next word in a moment…</p>';
}

function quickPage(session){
 if(quickFeedback?.sessionId===session.id&&quickRunning)return quickFeedbackPage(session);
 if(session.status==='completed'){const correct=session.answers.filter(a=>a.outcome==='correct').length,unknown=session.answers.filter(a=>a.reason==='unknown').length,timeouts=session.answers.filter(a=>a.reason==='timeout').length,wrong=session.answers.filter(a=>a.outcome==='incorrect').length;const unique=[...new Set(session.questions.map(q=>q.wordID))];return heading('Quick Match complete','Your answers are saved and included in your existing word ratings.')+'<div class="stack"><section class="card"><div class="score">'+correct+'<span style="font-size:25px"> / 30</span></div><p class="sub">Correct answers</p><div class="row wrap block">'+badge((30-correct)+' incorrect / not correct','orange')+badge(wrong+' wrong choice')+badge(unknown+' I don’t know')+badge(timeouts+' timed out')+'</div><p class="caption block">Each correct answer earns one point. Wrong choices, “I don’t know”, and timeouts earn zero. Unknown and timed-out answers use the existing unknown outcome in your review schedule.</p><div class="row wrap block">'+button('Play again','quick-again','primary','data-save-action')+button('Back to quiz setup','quiz-setup')+'</div></section><section class="card"><h2>Your word ratings</h2>'+unique.map(id=>{const q=session.questions.find(q=>q.wordID===id),word=data.words.find(w=>w.id===id)||{id};return '<div class="quick-word-result"><strong>'+esc(q.prompt)+'</strong>'+wordStars(word)+'</div>'}).join('')+'</section><details class="card"><summary>Review all 30 answers</summary>'+session.questions.map((q,i)=>{const a=session.answers.find(a=>a.questionID===q.id),correct=q.choices.find(c=>c.id===q.correctID);return '<div class="quick-word-result"><strong>'+(i+1)+'. '+esc(q.prompt)+'</strong><p class="caption">'+esc(correct.label)+' · '+(a.reason==='timeout'?'Timed out':a.reason==='unknown'?'I don’t know':a.outcome==='correct'?'Correct':'Incorrect')+'</p></div>'}).join('')+'</details></div>'}
 if(!quickRunning)return quickReady(session);
 const q=session.questions[session.currentIndex];return heading('Quick Match','Choose the Russian meaning.',button('Leave game','quick-leave'))+'<div class="row between"><strong>Question '+(session.currentIndex+1)+' of 30</strong><span class="caption">'+session.answers.filter(a=>a.outcome==='correct').length+' correct</span></div><div class="quiz-progress" role="progressbar" aria-label="Game completion" aria-valuemin="0" aria-valuemax="30" aria-valuenow="'+session.answers.length+'"><span style="width:'+session.answers.length/30*100+'%"></span></div><section class="card question quick-question"><div class="row between"><span class="eyebrow">ENGLISH WORD</span><span class="quick-time" id="quick-seconds" role="timer" aria-label="Seconds remaining">4.0s</span></div><h2 class="prompt" id="quick-prompt" tabindex="-1">'+esc(q.prompt)+'</h2><div class="quick-time-track" aria-hidden="true"><span id="quick-time-bar"></span></div></section>'+quickChoiceButtons(q)+'<p class="caption block">Tap a translation · instant feedback · four seconds per word</p>';
}
function refreshQuickClock(){
 quickClock.stop();const s=data.sessions.find(s=>s.id===quizID);if(!storageReady||!quickRunning||route!=='quiz'||s?.kind!=='quick_match'||quickSubmitting)return;
 if(quickFeedback?.sessionId===s.id){const id=quickFeedback.question.id;quickClock.arm('feedback:'+id,quickFeedback.until,()=>{if(quickFeedback?.question.id!==id)return;quickFeedback=null;render();$('#quick-prompt')?.focus({preventScroll:true});if(s.status==='completed')scrollTop()});return}if(s.status!=='in_progress')return;
 const q=s.questions[s.currentIndex],key=s.id+':'+q.id;
 quickClock.arm(key,s.deadline,()=>{if(busy){setTimeout(refreshQuickClock,75);return}quickRespond(q.id,null,'timeout').catch(fail)},remaining=>{const label=$('#quick-seconds'),bar=$('#quick-time-bar');if(label)label.textContent=(remaining/1000).toFixed(1)+'s';if(bar)bar.style.width=remaining/4000*100+'%'});
}
async function quickRespond(qid,selected,reason='answer'){
 if(quickSubmitting||quickFeedback||busy||!quickRunning||route!=='quiz')return;
 const current=data.sessions.find(s=>s.id===quizID);if(current?.kind!=='quick_match'||current.status!=='in_progress'||current.questions[current.currentIndex]?.id!==qid)return;
 quickSubmitting=true;quickClock.stop();const shown=C.clone(current.questions[current.currentIndex]),answeredAt=Date.now();try{const session=await mutation(s=>C.answerQuick(s,current.id,qid,selected,answeredAt,reason,650));if(session){const answer=session.answers.find(a=>a.questionID===qid);quickFeedback={sessionId:session.id,question:shown,answer:C.clone(answer),until:answeredAt+650};render()}else{quickRunning=false;render()}}finally{quickSubmitting=false;refreshQuickClock()}
}

function activeQuiz(session){
 const q=session.questions[session.currentIndex],answer=session.answers.find(a=>a.questionID===q.id),isComplete=session.status==='completed';
 return `${heading('A moment to practice',title(session.direction),button('Leave Quiz','leave'))}<div class="row between"><span class="eyebrow" style="margin:0">QUESTION ${session.currentIndex+1} OF 5</span><span class="caption">${session.answers.length} answers saved</span></div><div class="quiz-progress" role="progressbar" aria-label="Quiz completion" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${session.answers.length}"><span style="width:${(session.answers.length/5)*100}%"></span></div><div class="stack"><section class="card question"><div class="caption">Choose the ${session.direction==='enRu'?'Russian meaning':'English expression'} used in this context.</div><h2 class="prompt">${esc(q.prompt)}</h2><p class="context">${esc(q.context)}</p></section><div class="choices" role="group" aria-label="Answer choices">${[...q.choices,{id:'unknown',label:"I don't know"}].map((choice,i)=>{
 const chosen=answer?(answer.selectedID??'unknown')===choice.id:selection===choice.id,correct=!!answer&&choice.id===q.correctID;
 return `<button type="button" class="choice ${chosen?'selected':''} ${correct?'correct':''} ${answer&&chosen&&answer.outcome==='incorrect'?'wrong':''}" data-action="choose-answer" data-id="${esc(choice.id)}" aria-pressed="${chosen}" ${answer?'disabled':''}><span class="num">${i<5?i+1:'?'}</span><span>${esc(choice.label)}</span><span class="check">${correct?'✓':chosen?(answer?'×':'●'):''}</span></button>`;
 }).join('')}</div>${answer?`<section class="card feedback ${answer.outcome}" aria-live="polite">${feedback(answer)}</section><div class="row between quiz-actions"><span class="caption">Response saved${isComplete?' · review schedule updated':''}</span>${button(isComplete?'View Results →':'Next →',isComplete?'results':'next','primary','data-save-action')}</div>`:`<div class="row between quiz-actions"><span class="caption">${selection===null?'Choose an answer to continue.':'Ready? Check your answer.'}<span class="keyboard-hint" style="display:block"><kbd>1</kbd>–<kbd>5</kbd> choose · <kbd>?</kbd> skip · <kbd>Enter</kbd> check</span></span>${button('Check Answer','apply','primary',`data-save-action ${selection===null?'disabled':''}`)}</div>`}</div>`;
}
function choiceFeedback(choice,label){return `<div class="feedback-section"><div class="label">${esc(label)}</div><div class="feedback-label">${esc(choice.label)}</div><p>${esc(choice.definition)}</p><p class="feedback-example">${esc(choice.example)}</p></div>`;}
function feedback(answer){return `<h2>${answer.outcome==='correct'?'✓ Correct':answer.outcome==='unknown'?'Let’s learn this one':'Keep practicing'}</h2>${choiceFeedback(answer.correctFeedback,'Correct answer')}${answer.outcome==='incorrect'&&answer.selectedFeedback?choiceFeedback(answer.selectedFeedback,'Your selected answer'):''}`;}
function review(session){return `${heading(session.status==='completed'?'Practice complete.':'Saved quiz',`${title(session.direction)} · ${date(session.completedAt??session.startedAt)}`)}<div class="card row between"><div><div class="score">${session.answers.filter(a=>a.outcome==='correct').length}<span style="font-size:25px;color:var(--muted)"> / 5</span></div><span class="caption">Correct answers</span></div><div class="counts">${['correct','incorrect','unknown'].map((o,i)=>badge(`${session.answers.filter(a=>a.outcome===o).length} ${o}`,['green','orange','gray'][i])).join('')}</div></div>${session.questions.map((q,i)=>{const a=session.answers.find(a=>a.questionID===q.id);return `<section class="card"><div class="label">Question ${i+1}</div><h2>${esc(q.prompt)}</h2><p class="sub">${esc(q.context)}</p><div class="block">${q.choices.map(c=>`<div class="review-choice ${c.id===q.correctID?'correct':''}">${c.id===q.correctID?'✓':'○'} ${esc(c.label)}${a?.selectedID===c.id?' · your answer':''}</div>`).join('')}</div><div class="divider"></div>${a?feedback(a):'<p class="muted">Not answered yet</p>'}</section>`;}).join('')}`;}
function progressCard(w,d){const l=data.learning[`${w.id}:${d}`]||C.initialLearning();return `<div class="learning"><strong>${title(d)}</strong><p class="caption">${l.lastPracticed===null?'New · not practiced yet':l.nextReview<=Date.now()?'Review due':`Next review ${esc(dateOnly(l.nextReview))}`}</p>${l.lastPracticed===null?'':`<p class="caption">${l.repetitions} repetitions · ${l.intervalDays}-day interval</p>`}<p class="caption">${l.correctCount} correct · ${l.incorrectCount} incorrect · ${l.unknownCount} unknown</p></div>`;}

function githubSaved(w){return githubReceipt?.repository==='m-grigoryan/english-training'&&githubReceipt.words?.[w.id]===JSON.stringify([w.content,w.status,w.deletedAt,w.updatedAt]);}
function wordCloud(w){const saved=githubSaved(w),shared=TrainingVocabulary.isShared(w),text=saved?'Saved to GitHub':shared?'Included for everyone':github?.token?'Waiting for GitHub':'Only on this device';return '<span class="word-cloud '+(saved||shared?'in-cloud':'local-only')+'" title="'+esc(saved?'Last confirmed in your private GitHub repository.':shared?'Included in the platform’s shared vocabulary on every device.':'Not yet confirmed saved in GitHub.')+'"><span aria-hidden="true">'+(saved?'☁':shared?'✓':'◌')+'</span> '+text+'</span>';}
function wordStars(w){const r=C.wordRating(data,w.id),label=r.total?r.stars+' out of 5 stars · '+r.correct+' correct, '+r.incorrect+' incorrect, '+r.unknown+' unknown · '+r.total+' answers':'Not rated · answer a quiz question to build your rating';return '<div class="word-rating" role="img" aria-label="'+esc(label)+'"><span aria-hidden="true" class="rating-stars">'+('★'.repeat(r.stars)+'☆'.repeat(5-r.stars))+'</span><span class="caption">'+(r.total?r.stars+'/5 · '+r.total+' answer'+(r.total===1?'':'s'):'Not rated yet')+'</span></div>';}
function refreshGitHubStatus(){const status=$('#github-sync-status');if(status)status.textContent=github?.status||'Not connected. Words are saved only on this device.';const btn=$('[data-action="github-now"]');if(btn)btn.disabled=!github?.token||!!github.running;const stop=$('[data-action="github-disconnect"]');if(stop)stop.disabled=!github?.token;const connect=$('[data-action="github-connect"]');if(connect)connect.disabled=!!github?.running;const label=$('#storage-label');if(label&&storageReady)label.textContent=github?.token?github.status:'Shared vocabulary included · progress on this device';}
function githubSettings(){return '<section class="card github-card"><h2>☁ GitHub storage</h2><p class="sub">Connect each device to the same private repository. New words, edits, answers, and history are saved on this device first, then synced with GitHub.</p><p class="notice block" id="github-sync-status" role="status" aria-live="polite"></p><p class="caption block">Repository: m-grigoryan/english-training · Only a confirmed upload or download earns the cloud icon. Existing local vocabulary is merged on first connection.</p><label class="field block" for="github-token">Fine-grained GitHub access token<input type="password" id="github-token" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="github_pat_…" aria-describedby="github-token-help"></label><p class="caption" id="github-token-help">Create a token for only this repository with Contents: Read and write. Paste it here on each device. It stays in this page’s memory and is forgotten when you reload or close the page. Never paste it into chat or commit it to the repository.</p><div class="row wrap block">'+button('Connect & sync','github-connect','primary')+button('Sync now','github-now','',github?.token?'':'disabled')+button('Disconnect','github-disconnect','quiet',github?.token?'':'disabled')+'</div><p class="caption block">While connected, changes sync automatically and new changes from another device are checked about once a minute. Offline changes remain here until the next successful sync. If a token expires, reconnect. Do not make the data repository public: it contains your answers and history.</p><p class="caption block">Word rating: 5 × correct answers ÷ all answers, rounded to the nearest star, with a minimum of one star after the first answer. Unanswered words show “Not rated yet.” Both directions and unfinished quizzes count; unknown answers count as not correct.</p>'+(data.syncConflicts?.length?'<details class="block"><summary>Review '+data.syncConflicts.length+' preserved word versions</summary><p class="caption">When two versions differ, the latest edit is displayed. Earlier content is kept here for recovery.</p>'+data.syncConflicts.map((x,i)=>'<p class="block">'+esc(x.word.content.english_term)+' '+button('Open preserved version','github-conflict','small','data-id="'+i+'"')+'</p>').join('')+'</details>':'')+'</section>';}

function vocabularyPage(){
 const query=C.norm(search),filtered=words().filter(w=>(filter==='all'||w.status===filter)&&(!query||C.norm(w.content.english_term).includes(query)||w.content.russian_translations.some(t=>C.norm(t).includes(query)))).sort((a,b)=>(ascending?1:-1)*C.norm(a.content.english_term).localeCompare(C.norm(b.content.english_term)));
 const w=words().find(w=>w.id===selectedWord);
 return `${heading('Words worth knowing.','Your meanings, your examples, your growing vocabulary.',button('+ Add Word','add-word','primary'))}<div class="toolbar"><input id="word-search" aria-label="Search English or Russian" placeholder="Search English or Russian…" value="${esc(search)}"><select id="word-filter" aria-label="Vocabulary status"><option value="all" ${filter==='all'?'selected':''}>All words</option><option value="ready" ${filter==='ready'?'selected':''}>Ready</option><option value="draft" ${filter==='draft'?'selected':''}>Drafts</option></select>${button(ascending?'↓ A–Z':'↑ Z–A','sort')}</div><div class="row between" style="margin-bottom:13px"><span class="label" style="margin:0">${filtered.length} WORD${filtered.length===1?'':'S'}</span>${button('Import JSON','import-files','quiet small')}</div><div class="library-layout"><div class="card word-list">${filtered.length?filtered.map(word=>{const l=data.learning[`${word.id}:enRu`]||C.initialLearning();return `<button type="button" class="word-item ${selectedWord===word.id?'selected':''}" data-action="select-word" data-id="${esc(word.id)}" aria-pressed="${selectedWord===word.id}"><div class="row between"><strong>${esc(wordTitle(word))}</strong>${badge(word.status==='ready'?'Ready':'Draft',word.status==='ready'?'green':'orange')}</div><div class="translation">${esc(word.content.russian_translations.join('; '))||'Translations not added yet'}</div>${wordCloud(word)}${wordStars(word)}<div class="caption">${l.lastPracticed===null?'New in English → Russian':`${l.correctCount} correct · ${l.intervalDays}-day interval`}</div></button>`;}).join(''):empty('Aa',words().length?'No matches':'Your collection starts here',words().length?'Try another search or filter.':'Add a word or import a completed vocabulary JSON file.')}</div><div>${w?wordDetail(w):`<div class="card">${empty('Aя','Make words your own.','Select a word to explore its meaning, bilingual examples, and learning progress.')}</div>`}</div></div>`;
}
function wordDetail(w){const c=w.content,supported=!!C.resolve(c,D);return `<div class="word-detail"><div class="card"><div class="row between">${badge(w.status==='ready'?'Ready to learn':'Draft',w.status==='ready'?'green':'orange')}<div class="row">${button('Edit','edit-word','small',`data-id="${esc(w.id)}"`)}${button('Delete','delete-word','small danger',`data-id="${esc(w.id)}"`)}</div></div><h2 class="detail-title">${esc(wordTitle(w))}</h2>${wordCloud(w)}${wordStars(w)}<p class="muted">${esc(c.russian_translations.join('; '))||'No translations yet'}</p>${w.status==='draft'?'<div class="notice block">Drafts stay out of quizzes until every required field is complete.</div>':!supported?'<div class="notice warn block">This meaning is saved. Offline quiz safety cannot yet be verified. See Supported Meanings in Settings.</div>':''}</div><section class="card"><h2>Meaning</h2><div class="block"><div class="label">ENGLISH</div><p>${esc(c.explanation_en)||'Not added yet'}</p></div><div class="block"><div class="label">RUSSIAN</div><p>${esc(c.explanation_ru)||'Not added yet'}</p></div></section><section class="card"><h2 class="section-title">In context</h2>${c.examples.length?c.examples.map(e=>`<div class="bilingual"><p>${esc(e.en)||'English example not added'}</p><p class="muted">${esc(e.ru)||'Russian example not added'}</p></div>`).join(''):'<p class="muted">No examples yet</p>'}</section><section class="card"><h2>Learning progress</h2>${progressCard(w,'enRu')}${progressCard(w,'ruEn')}</section></div>`;}
function historyPage(){const selected=data.sessions.find(s=>s.id===selectedHistory);if(selected?.kind==='quick_match')return `<div class="stack">${button('← All quizzes','history-back')}${selected.status==='completed'?quickPage(selected):quickReady(selected)}</div>`;if(selected)return `<div class="stack"><div class="row between">${button('← All quizzes','history-back')}${selected.status==='in_progress'?button('Resume Quiz','resume','primary'):''}</div>${review(selected)}</div>`;const sessions=data.sessions.slice().sort((a,b)=>b.startedAt-a.startedAt);return `${heading('Look back. Learn more.','Every practice session, preserved exactly as you experienced it.')}<div class="history-list">${sessions.length?sessions.map(s=>`<button type="button" class="history-item" data-action="select-history" data-id="${esc(s.id)}"><div class="row between"><div><strong>${s.kind==='quick_match'?'Quick Match · 30 questions':title(s.direction)}</strong><p class="caption" style="margin-top:8px">${esc(date(s.completedAt??s.startedAt))}</p></div><span class="score-mini">${s.answers.filter(a=>a.outcome==='correct').length}/${s.questions.length}</span></div><div class="row between" style="margin-top:15px">${badge(s.status==='completed'?'Completed':'In progress',s.status==='completed'?'green':'orange')}<span class="caption">Review questions →</span></div></button>`).join(''):`<div class="card">${empty('↺','Your practice starts here.','Quizzes appear here with their saved questions, responses, and feedback.')}</div>`}</div>`;}
function settingsPage(){const records=data.imports.slice().sort((a,b)=>b.date-a.date).slice(0,100);return `${heading('A space for your learning.','Connect GitHub, manage storage, and bring vocabulary into your browser.')}<div class="settings-grid">${githubSettings()}<section class="card"><h2>Appearance</h2><p class="sub">Choose a comfortable reading experience. Your preference is saved in this browser.</p><div class="theme-controls block" role="group" aria-label="Appearance">${['dark','light','system'].map(mode=>button(mode[0].toUpperCase()+mode.slice(1),'set-theme','',`data-id="${mode}" aria-pressed="${appearance()===mode}" data-save-action`)).join('')}</div><p class="caption block">System follows your Mac’s appearance setting. You can also switch quickly from the sidebar.</p></section><section class="card"><div class="row between"><h2>Local browser storage</h2>${badge('Offline ready','green')}</div><p class="sub">The platform includes 76 shared words for everyone. Your added words, edits, quiz snapshots, answers, and schedules are saved in this browser profile using IndexedDB. This HTML file contains everything needed to run offline.</p><div class="notice warn block">Use the same browser, profile, and file location each time. Private browsing, clearing website data, changing origins, or browser storage eviction can remove access to your data. The browser version starts separately from the macOS app’s database.</div><p class="caption block">If this browser blocks storage for a local file, use the included localhost server and its fixed address. GitHub receives your vocabulary and learning history only after you connect GitHub sync.</p></section><section class="card"><div class="row between wrap"><h2>JSON vocabulary import</h2>${button('Import JSON Files…','import-files','primary')}</div><p class="sub">Choose one or more completed .json files. Each file creates one ready vocabulary entry after validation. The 1 MiB limit and duplicate checks apply to every file.</p><div class="divider"></div><h3>Automatic folder watching</h3><p class="caption block">${esc(importer?.status||'No folder selected')}</p>${data.settings.folderName?`<p class="caption">Saved folder: ${esc(data.settings.folderName)}</p>`:''}<div class="row wrap block">${window.showDirectoryPicker?button('Choose Folder…','choose-folder'):'<span class="caption">Folder watching is unavailable in this browser. Manual file import is available above.</span>'}${importer?.folder?button('Reconnect Folder','reconnect-folder'):''}${button('Retry Failed Files','retry-imports','quiet',importer?.folder?'':'disabled')}</div><p class="caption block">Folder access requires your permission and may need reconnecting after reopening. Watching runs only while this page is open, subject to browser background throttling. Producers must finish a .partial file and atomically rename it to .json. Three stable observations over at least four seconds are required before processing.</p><div class="notice block">${badge('ChatGPT write workflow · unverified','orange')}<p style="margin-top:9px">Selecting files or a folder does not connect ChatGPT or grant it write access. An authorized external workflow must write the JSON. No such workflow has been verified.</p></div></section><section class="card"><div class="row between"><h2>Recent imports</h2><span class="caption">Last 100 records</span></div>${records.length?records.map(r=>`<div class="import-record"><div class="row between"><span class="file-name">${esc(r.path)}</span>${badge(r.status==='success'?'Imported':'Needs attention',r.status==='success'?'green':'orange')}</div><p style="font-size:13px">${esc(r.message)}</p><div class="row between"><span class="caption">${esc(date(r.date))}</span>${r.wordID?button('Open Entry','select-word','quiet small',`data-id="${esc(r.wordID)}"`):''}</div></div>`).join(''):'<p class="caption block">No imports yet. Files stay in their original folder, including failed files that need correction.</p>'}</section><section class="card"><h2>Offline quiz safety</h2><p class="sub">Save any vocabulary. Quizzes support the curated meanings below, including their listed English aliases and Russian translations. Other senses fail with an actionable error. Your own stored definitions and examples are used in questions and feedback.</p><details class="block" id="supported-meanings"><summary>Supported Meanings (${D.length})</summary><div class="meanings">${D.map(m=>`<div class="meaning"><strong>${esc(m.aliases.join(', '))}</strong><span>${esc(m.content.russian_translations.join('; '))}</span></div>`).join('')}</div></details></section><section class="card"><h2>How to use English Training</h2><ol class="guide"><li>Add a word with both explanations, translations, and complete bilingual examples. Save unfinished work as a draft. Use the attempt sample if you want a first supported meaning.</li><li>Choose a quiz direction. Select an answer or I don't know, then Apply. Read the feedback before choosing Next.</li><li>Leave and resume anytime. Submitted answers survive closing the tab or browser. Completed quizzes are preserved in History after word edits or deletion.</li><li>Each direction has its own schedule. Correct sessions progress through 1 day, 6 days, then multiplied intervals. Any incorrect or unknown attempt resets that word for the next day, once per session.</li></ol><div class="divider"></div><p class="caption">GitHub sync merges vocabulary and history across your connected devices. Your GitHub account controls access; this app has no separate account.</p></section></div>`;}
function readEditor(){if(!editing)return;document.querySelectorAll('[data-editor-field]').forEach(el=>{const p=el.dataset.editorField.split('.');if(p[0]==='translation')editing.content.russian_translations[Number(p[1])]=el.value;else if(p[0]==='example')editing.content.examples[Number(p[1])][p[2]]=el.value;else editing.content[p[0]]=el.value;});}
function editorMarkup(){const c=editing.content;return `<div class="dialog-head"><h2 id="editor-title">${data.words.some(w=>w.id===editing.id)?'Edit word':'Add a word'}</h2><p class="caption" style="margin-top:7px">Capture a meaning. Bring it to life with examples.</p></div><div class="dialog-content"><label class="field">English word or phrase<input id="editor-term" data-editor-field="english_term" value="${esc(c.english_term)}" placeholder="e.g. attempt" maxlength="300"></label><div class="fields"><h3>Russian translations</h3>${c.russian_translations.map((t,i)=>`<div class="translation-field"><input aria-label="Russian translation ${i+1}" data-editor-field="translation.${i}" value="${esc(t)}" placeholder="Russian translation">${button('−','remove-translation','',`data-index="${i}" aria-label="Remove translation ${i+1}"`)}</div>`).join('')}${button('+ Add Translation','add-translation','quiet')}</div><label class="field">English explanation<textarea data-editor-field="explanation_en" placeholder="Explain this specific meaning in English…">${esc(c.explanation_en)}</textarea></label><label class="field">Russian explanation<textarea data-editor-field="explanation_ru" placeholder="Explain the same meaning in Russian…">${esc(c.explanation_ru)}</textarea></label><div class="fields"><h3>Bilingual examples</h3>${c.examples.map((e,i)=>`<div class="example-fields"><div class="row between"><strong class="caption">Example ${i+1}</strong>${button('Remove','remove-example','quiet small',`data-index="${i}"`)}</div><label class="field">English sentence<textarea data-editor-field="example.${i}.en">${esc(e.en)}</textarea></label><label class="field">Russian sentence<textarea data-editor-field="example.${i}.ru">${esc(e.ru)}</textarea></label></div>`).join('')}${button('+ Add Example Pair','add-example','quiet')}</div><div id="editor-error" role="alert">${editorError?`<div class="notice error">${esc(editorError)}${editorDuplicate?`<div class="block">${button('Open Existing Entry','editor-open-duplicate','small')}</div>`:''}</div>`:''}</div><p class="caption">Save requires every field and at least one complete bilingual example. Save as Draft keeps unfinished work out of quizzes.</p>${!data.words.some(w=>w.id===editing.id)?button('Fill with the attempt example','editor-example','quiet small'):''}</div><div class="dialog-foot">${button('Cancel','editor-cancel','cancel')}${button('Save as Draft','save-draft','','data-save-action')}${button('Save','save-ready','primary','data-save-action')}</div>`;}
function renderEditor(){const dialog=$('#editor-dialog'),top=dialog.querySelector('.dialog-content')?.scrollTop||0;dialog.innerHTML=editorMarkup();dialog.querySelector('.dialog-content').scrollTop=top;syncBusy();}
function openEditor(w){editing=w?C.clone(w):{id:C.uid(),content:C.blankContent()};originalEditor=JSON.stringify(editing);editorError=null;editorDuplicate=null;renderEditor();$('#editor-dialog').showModal();$('#editor-term').focus();}
function closeEditor(ask=true){readEditor();if(ask&&JSON.stringify(editing)!==originalEditor){$('#discard-dialog').showModal();return;}$('#editor-dialog').close();editing=null;}
async function saveEditor(status){readEditor();editorError=null;editorDuplicate=null;const input=C.clone(editing);busy=true;syncBusy();try{const result=await store.transact(s=>C.saveWord(s,input,status));data=result.state;selectedWord=result.result.id;route='vocabulary';$('#editor-dialog').close();editing=null;render();githubNotice=!!github?.token;notify((status==='ready'?'Word saved and ready to learn.':'Draft saved.')+(github?.token?' Saved on this device; uploading to GitHub…':' Saved only on this device. Connect GitHub in Settings to upload it.'));}catch(e){editorError=friendly(e);editorDuplicate=e.existingID||null;renderEditor();}finally{busy=false;syncBusy();}}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'});}
async function handleAction(action,el){
 if(action==='quick-start'||action==='quick-again'){
  if(busy||quickSubmitting)return;
  const s=await mutation(state=>{const requested=el.dataset.id&&state.sessions.find(q=>q.id===el.dataset.id&&q.kind==='quick_match'&&q.status==='in_progress');const session=requested||C.startQuick(state,D);if(session.deadline<=Date.now())C.answerQuick(state,session.id,session.questions[session.currentIndex].id,null,Date.now(),'timeout');return session});
  if(s){quickFeedback=null;quickRunning=true;quizID=s.id;route='quiz';showResults=false;selection=null;render();scrollTop();$('#quick-prompt')?.focus({preventScroll:true})}return;
 }
 if(action==='quick-answer'){await quickRespond(el.dataset.question,el.dataset.id==='unknown'?null:el.dataset.id);return;}
 if(action==='quick-leave'){quickRunning=false;quickFeedback=null;quickClock.stop();quizID=null;render();scrollTop();return;}

 if(action==='github-connect'){const field=$('#github-token'),token=field.value.trim();field.value='';try{await github.connect(token);notify('Words and history saved to GitHub. Cloud icons confirm saved words.');render()}catch(e){refreshGitHubStatus();fail(e)}return;}
 if(action==='github-now'){try{await github.sync();render();notify('GitHub sync finished.')}catch(e){refreshGitHubStatus();fail(e)}return;}
 if(action==='github-disconnect'){github.disconnect();render();notify('Disconnected. Your local words and saved GitHub data are preserved.');return;}
 if(action==='github-conflict'){const item=data.syncConflicts?.[Number(el.dataset.id)];if(item){openEditor();editing.content=C.clone(item.word.content);renderEditor()}return;}

 if(action==='set-theme'){await setAppearance(el.dataset.id);return;}
 if(action==='toggle-theme'){const mode=appearance(),dark=mode==='dark'||(mode==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches);await setAppearance(dark?'light':'dark');return;}
 if(action==='add-word'){openEditor();return;}
 if(action==='edit-word'){openEditor(words().find(w=>w.id===el.dataset.id));return;}
 if(action==='editor-cancel'){closeEditor();return;}
 if(action==='discard-cancel'){$('#discard-dialog').close();return;}
 if(action==='discard-confirm'){$('#discard-dialog').close();closeEditor(false);return;}
 if(action==='save-draft'||action==='save-ready'){if(!busy)await saveEditor(action==='save-draft'?'draft':'ready');return;}
 if(action==='editor-open-duplicate'){const id=editorDuplicate;$('#editor-dialog').close();editing=null;route='vocabulary';selectedWord=id;render();return;}
 if(['add-translation','remove-translation','add-example','remove-example','editor-example'].includes(action)){
  readEditor();if(action==='add-translation')editing.content.russian_translations.push('');if(action==='remove-translation')editing.content.russian_translations.splice(Number(el.dataset.index),1);if(action==='add-example')editing.content.examples.push({en:'',ru:''});if(action==='remove-example')editing.content.examples.splice(Number(el.dataset.index),1);if(action==='editor-example')editing.content=C.clone(D.find(m=>m.id==='attempt').content);renderEditor();return;
 }
 if(action==='delete-word'){const w=words().find(w=>w.id===el.dataset.id);$('#delete-description').textContent=`Delete “${wordTitle(w)}”? It will be hidden from new quizzes. Saved sessions and history remain available.`;$('#delete-confirm').dataset.id=w.id;$('#delete-dialog').showModal();return;}
 if(action==='delete-cancel'){$('#delete-dialog').close();return;}
 if(action==='delete-confirm'){const id=el.dataset.id;await mutation(s=>C.deleteWord(s,id));$('#delete-dialog').close();selectedWord=null;render();return;}
 if(action==='dismiss-error'){error=null;errorID=null;renderAlert();return;}
 if(action==='open-duplicate'){selectedWord=errorID;route='vocabulary';error=null;errorID=null;render();return;}
 if(action==='direction'){direction=el.dataset.id;render();return;}
 if(action==='start'){const session=await mutation(s=>C.start(s,direction,D));if(session){quizID=session.id;selection=null;showResults=false;render();scrollTop();}return;}
 if(action==='resume'){const s=(selectedHistory?data.sessions.find(s=>s.id===selectedHistory&&s.status==='in_progress'):null)||active();if(s){quickRunning=false;quizID=s.id;route='quiz';selection=null;showResults=false;render();scrollTop();}return;}
 if(action==='choose-answer'){selection=el.dataset.id;render();document.querySelector('.choice[data-id="'+selection+'"]')?.focus({preventScroll:true});return;}
 if(action==='apply'){if(selection===null)return;const current=data.sessions.find(s=>s.id===quizID),s=await mutation(state=>C.submit(state,current.id,current.questions[current.currentIndex].id,selection==='unknown'?null:selection));if(s){render();const fb=$('.feedback');fb?.scrollIntoView({block:'nearest',behavior:'smooth'});}return;}
 if(action==='next'){const s=await mutation(state=>C.next(state,quizID));if(s){selection=null;render();scrollTop();}return;}
 if(action==='results'){showResults=true;render();scrollTop();return;}
 if(action==='quiz-setup'||action==='leave'){quickRunning=false;quickFeedback=null;quickClock.stop();quizID=null;showResults=false;selection=null;render();scrollTop();return;}
 if(action==='select-word'){selectedWord=el.dataset.id;route='vocabulary';render();return;}
 if(action==='sort'){ascending=!ascending;render();return;}
 if(action==='select-history'){selectedHistory=el.dataset.id;render();scrollTop();return;}
 if(action==='history-back'){selectedHistory=null;render();scrollTop();return;}
 if(action==='import-files'){$('#json-files').click();return;}
 if(action==='choose-folder'||action==='reconnect-folder'){try{if(action==='choose-folder')await importer.choose();else await importer.reconnect();data=await store.read();render();}catch(e){if(e.name!=='AbortError')fail(e);}return;}
 if(action==='retry-imports'){importer.attempted.clear();await importer.scan();data=await store.read();render();notify('Retry started. Changing files will settle before import.');return;}
 if(action==='retry-start'){location.reload();return;}
}
document.addEventListener('click',e=>{const routeButton=e.target.closest('[data-route]');if(routeButton){quickRunning=false;quickFeedback=null;quickClock.stop();route=routeButton.dataset.route;render();scrollTop();return;}const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el).catch(fail);});
document.addEventListener('input',e=>{if(e.target.id==='word-search'){search=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='word-filter'){filter=e.target.value;render();}});
$('#editor-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});
$('#json-files').addEventListener('change',async e=>{const files=Array.from(e.target.files);e.target.value='';if(!files.length)return;try{const result=await importer.manual(files);data=await store.read();render();notify(`${result.success} imported · ${result.failed} failed · ${result.skipped} already processed`);}catch(e){fail(e);}});
window.addEventListener('unhandledrejection',e=>{e.preventDefault();fail(e.reason);});
window.addEventListener('pageshow',async()=>{if(storageReady)try{data=await store.read();render();}catch(e){fail(e);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&editing){e.preventDefault();if(!busy)saveEditor('ready');}});
document.addEventListener('keydown',e=>{
 if(e.defaultPrevented||e.repeat||e.metaKey||e.ctrlKey||e.altKey||busy||!storageReady||route!=='quiz'||showResults||document.querySelector('dialog[open]')||e.target.closest('input,textarea,select,[contenteditable]'))return;
 const session=data.sessions.find(s=>s.id===quizID);if(!session)return;
 if(session.kind==='quick_match'){
  if(quickRunning&&session.status==='in_progress'&&['1','2','?'].includes(e.key)){e.preventDefault();quickRespond(session.questions[session.currentIndex].id,e.key==='?'?null:session.questions[session.currentIndex].choices[Number(e.key)-1].id).catch(fail)}return;
 }
 const q=session.questions[session.currentIndex],answered=session.answers.some(a=>a.questionID===q.id);
 if(!answered&&(/^[1-5]$/.test(e.key)||e.key==='?')){e.preventDefault();const id=e.key==='?'?'unknown':q.choices[Number(e.key)-1].id;const choice=Array.from(document.querySelectorAll('.choice')).find(b=>b.dataset.id===id);if(choice&&!choice.disabled)choice.click();return;}
 if(e.key==='Enter'&&!e.target.closest('button,a')){const action=answered?(session.status==='completed'?'results':'next'):'apply';const control=document.querySelector('[data-action="'+action+'"]');if(control&&!control.disabled){e.preventDefault();control.click();}}
 if(e.key==='Enter'&&e.target.closest('.choice')){const control=document.querySelector('[data-action="apply"]');if(control&&!control.disabled){e.preventDefault();control.click();}}
});
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyAppearance);
async function boot(){render();try{await store.open();data=await store.read();storageReady=true;
 try{githubReceipt=await store.githubReceipt()}catch{githubReceipt=null}
 github=new TrainingGitHub.GitHubSync(store,{onStatus:()=>refreshGitHubStatus(),onData:async(state,receipt)=>{
  const oldTerm=data.words.find(w=>w.id===selectedWord)?.content.english_term;data=state;githubReceipt=receipt;
  try{await store.githubReceipt(receipt)}catch{githubReceipt=null;notify('GitHub saved your data, but this browser could not keep the cloud confirmation. Sync again to verify.')}
  if(oldTerm&&!data.words.some(w=>w.id===selectedWord))selectedWord=data.words.find(w=>C.norm(w.content.english_term)===C.norm(oldTerm))?.id||null;
  render();if(githubNotice){githubNotice=false;notify('☁ Words and history saved to GitHub.')}
 }});
 setInterval(()=>{if(github?.token&&!document.hidden)github.sync().catch(()=>{})},60000);
 window.addEventListener('online',()=>{if(github?.token)github.sync().catch(()=>{})});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&github?.token)github.sync().catch(()=>{})});
 const current=active();if(current)quizID=current.id;importer=new TrainingImporter(store,async state=>{if(state)data=state;else try{data=await store.read();}catch(e){fail(e);}if(route==='settings'||route==='vocabulary'||(!quizID&&route==='quiz'))render();});store.listeners.push(async e=>{if(e){fail(e);return;}try{data=await store.read();render();}catch(e){fail(e);}});render();await importer.restore();setInterval(()=>importer.scan(),2000);}catch(e){error=friendly(e);$('#page').innerHTML=`<div class="card">${empty('!','Browser storage is unavailable.','Open this file in a normal Chrome window. If storage is still blocked, run the included local server and open its fixed localhost address.',button('Try Again','retry-start','primary'))}<div class="notice error">${esc(error)}</div></div>`;$('#storage-label').textContent='Storage unavailable · no data saved';}}
boot();
})();
